    v_batch_size  NUMBER := 10;
    v_row_count   NUMBER := 0;
    v_status_text VARCHAR2(4000) := arg2;
    v_visit_count NUMBER;
    v_dummy       NUMBER;
    v_case        VARCHAR2(30) := NULL;
BEGIN
    IF v_threshold < 3 THEN
        v_case := 'RESTAURANT';

        FOR r IN (
            SELECT "ResID", "ResName", "Address"
            FROM "Restaurant"
            WHERE "ResID" < arg1
              AND "ResName" LIKE arg2
