            IF r."ResID" > 25 THEN
                UPDATE "Restaurant"
                SET "ResName" = 'PROMOTED'
                WHERE "ResID" = r."ResID";
            ELSIF r."Address" = arg3 THEN
                SELECT COUNT(*)
                INTO v_visit_count
                FROM "Visits_Restaurant" vr
                JOIN "Student" s
                  ON s."StuID" = vr."StuID"
                WHERE vr."ResID" = r."ResID"
                  AND s."LName" = arg5;

                IF v_visit_count > 0 THEN
                    UPDATE "Restaurant"
                    SET "Address" = 'RETAINED'
                    WHERE "ResID" = r."ResID";
                ELSE
                    DELETE FROM "Restaurant"
                    WHERE "ResID" = r."ResID"
                      AND "ResName" = r."ResName";

                    DELETE FROM "Visits_Restaurant"
                    WHERE "ResID" = r."ResID";

                    DELETE FROM "Type_Of_Restaurant"
                    WHERE "ResID" = r."ResID";
                END IF;
            ELSE
                UPDATE "Restaurant"
                SET "Address" = 'PENDING'
                WHERE "ResID" = r."ResID";

                UPDATE "Restaurant"
                SET "Rating" = arg6
                WHERE "ResID" = r."ResID";
            END IF;

            IF v_row_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

    ELSIF v_threshold < 8 THEN
        v_case := 'STUDENT';

        FOR s IN (
            SELECT "StuID", "LName"
            FROM "Student"
            WHERE "StuID" BETWEEN arg4 - 5 AND arg4 + 15
        ) LOOP
            v_row_count := v_row_count + 1;

            IF s."LName" = arg5 THEN
                UPDATE "Student"
                SET "Major" = 700
                WHERE "StuID" = s."StuID"
                  AND "LName" = s."LName";
            END IF;

            IF s."LName" LIKE 'ACTIVE%' THEN
                UPDATE "Student"
                SET "LName" = 'PROCESSED'
                WHERE "StuID" = s."StuID"
                  AND "LName" = s."LName";
            ELSIF s."StuID" > arg4 + 5 THEN
                v_threshold := v_threshold + s."StuID";
            ELSE
                IF s."LName" = 'EXPIRED' THEN
                    DELETE FROM "Student"
                    WHERE "StuID" = s."StuID"
                      AND "LName" = s."LName";
                END IF;
            END IF;

            IF v_row_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

    ELSIF v_threshold < 18 THEN
        v_case := 'TYPE';

        FOR t IN (
            SELECT "ResTypeID"
            FROM "Restaurant_Type"
            WHERE "ResTypeID" > arg6 - 20
        ) LOOP
            v_row_count := v_row_count + 1;

            IF t."ResTypeID" < 50 THEN
                v_status_text := 'LOW_PRIORITY';
            ELSIF t."ResTypeID" < 150 THEN
                v_status_text := 'MEDIUM_PRIORITY';
            ELSE
                v_status_text := 'HIGH_PRIORITY';
            END IF;

            UPDATE "Restaurant_Type"
            SET "ResTypeID" = "ResTypeID" + 10
            WHERE "ResTypeID" = t."ResTypeID";

            UPDATE "Type_Of_Restaurant"
            SET "ResTypeID" = "ResTypeID" + 10
            WHERE "ResTypeID" = t."ResTypeID";

            IF v_row_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

    ELSIF v_threshold < 25 THEN
        v_case := 'ARCHIVE';

        UPDATE "Restaurant"
        SET "Address" = 'ARCHIVED'
        WHERE "ResID" < arg1
          AND "ResName" <> arg2;

        SELECT 1 INTO v_dummy FROM "Restaurant" WHERE 1 = 0;

    ELSIF v_threshold < 40 THEN
        v_case := 'OBSOLETE';

        DELETE FROM "Student"
        WHERE "StuID" < arg4
          AND "LName" = 'OBSOLETE';

        SELECT 1 INTO v_dummy FROM "Student" WHERE 1 = 0;

    ELSE
        v_case := 'DEFAULT';

        UPDATE "Restaurant_Type"
        SET "ResTypeID" = arg6 + 100
        WHERE "ResTypeID" > 200;

        SELECT 1 INTO v_dummy FROM "Restaurant_Type" WHERE 1 = 0;
    END IF;

    IF v_status_text = 'HIGH_PRIORITY' THEN
        UPDATE "Restaurant_Type"
        SET "ResTypeID" = "ResTypeID" * 2
        WHERE "ResTypeID" > 100;
    ELSIF v_case = 'ARCHIVE' THEN
        DELETE FROM "Restaurant"
        WHERE "Address" = 'ARCHIVED'
          AND "ResID" < v_threshold - 10;
    ELSIF v_row_count > 15 THEN
        UPDATE "Student"
        SET "LName" = 'BULK_PROCESSED'
        WHERE "StuID" BETWEEN arg4 AND arg4 + 50;
    ELSE
        UPDATE "Restaurant"
        SET "ResName" = arg3
        WHERE "ResID" > v_threshold;
    END IF;
END;
